function renderTopbar(){
  $("#topSlot").textContent=state.saveMeta.slotName||"未建档";$("#topSystem").textContent=`系统：${state.config.system||"未选择"}`;$("#topPhase").textContent=`阶段：${phaseLabel(state.runtime.phase)}`;$("#topConnection").textContent=`API：${({untested:"未测试",ok:"可用",failed:"失败"})[state.runtime.connection]||state.runtime.connection}`;
}
function meter(label,current,max){const pct=max?clamp(current/max*100,0,100):0;return `<div class="meter"><div class="meter-head"><span>${escapeHtml(label)}</span><span>${escapeHtml(current)} / ${escapeHtml(max)}</span></div><div class="bar"><span style="width:${pct}%"></span></div></div>`}
function tensionStage(current,max=6){
  const safeMax=Math.max(1,Number(max||6)),normalized=clamp(Number(current||1),1,safeMax),level=Math.max(1,Math.min(6,Math.ceil(normalized/safeMax*6)));
  return [
    {label:"局势平静",description:"威胁尚未主动介入，调查仍有余裕。"},
    {label:"异常显现",description:"环境或相关人物开始出现可疑变化。"},
    {label:"威胁正在行动",description:"对手或环境开始主动施压；张力本身不会直接修改骰点。"},
    {label:"危险逼近",description:"证据、路线或 NPC 可能受到主动干预。"},
    {label:"危机临界",description:"直接冲突、追逐或重大损失即将发生。"},
    {label:"危机爆发",description:"局势进入高潮，应尽快作出关键决断。"}
  ][level-1]
}
function investigationStage(current){
  const value=clamp(Number(current||0),0,100);
  if(value>=100)return{label:"调查充分",description:"当前调查目标已获得充分推进。"};
  if(value>=80)return{label:"证据收束",description:"主要脉络已经形成，接近作出结论。"};
  if(value>=60)return{label:"接近核心",description:"关键问题逐步明确，仍需补足证据。"};
  if(value>=30)return{label:"案情展开",description:"线索之间开始建立联系。"};
  if(value>=10)return{label:"线索成形",description:"已有若干线索，但尚不足以形成稳定判断。"};
  return{label:"调查起步",description:"目前只掌握少量有效信息。"}
}
function situationMeter(label,current,max,status){return `${meter(label,current,max)}<div class="small" style="margin:4px 0 9px"><strong>${escapeHtml(status.label)}</strong><div class="muted">${escapeHtml(status.description)}</div></div>`}

function chips(items,label="name"){return items?.length?`<div class="chip-list">${items.map(x=>`<span class="chip">${escapeHtml(typeof x==="string"?x:x[label]||x.id)}</span>`).join("")}</div>`:`<div class="muted">无</div>`}
function renderClueSummary(items){return items?.length?items.map(clue=>`<div class="audit"><strong>${escapeHtml(clue.name||clue.id)}</strong>${clue.discoveryQualityLabel?` · ${escapeHtml(clue.discoveryQualityLabel)}`:""}<div class="muted small">${escapeHtml(clue.playerDescription||clue.description||"已记录")}</div></div>`).join(""):`<div class="muted">无</div>`}
function renderSidebar(){
  const c=state.character,node=getCurrentNode();let stats="<div class='muted'>尚未创建角色</div>";if(c){stats=`<div class="kv"><span>姓名</span><b>${escapeHtml(c.name)}</b><span>身份</span><b>${escapeHtml(c.occupation||c.className||c.race||"角色")}</b></div>${meter("HP",c.hp,c.maxHp)}${c.system==="coc7"?meter("SAN",c.san,c.maxSan):""}${c.creationValidation==="legacy_incomplete"?'<div class="notice warn" style="margin-top:8px">旧版角色卡的技能点未完整分配。<button id="fixCharacterBtn" class="btn" style="margin-top:6px">补完角色卡</button></div>':""}`}
  const skillEntries=Array.isArray(c?.skills)?c.skills.filter(x=>Number(x.value)>Number(x.base||0)||x.occupationSkill).sort((a,b)=>Number(b.value)-Number(a.value)).slice(0,14).map(x=>({name:`${x.name} ${x.value}${x.occupationSkill?"★":""}`})):isPlainObject(c?.skills)?Object.entries(c.skills).map(([k,v])=>({name:`${k} ${v>=0?"+":""}${v}`})):[],resourceEntries=Object.entries(state.resources||{}).map(([k,v])=>({name:`${k} ${v}`})),recentLogs=state.logs.filter(x=>state.config.kpDebug||!x.secret).slice(-6).reverse(),leads=(state.campaign.activeLeads||[]).filter(x=>x.status!=="resolved"),questions=(state.campaign.unresolvedQuestions||[]).filter(x=>x.status!=="resolved"),director=state.campaign.directorState||defaultDirectorState(),lastCheck=state.checkRecords.filter(x=>state.config.kpDebug||(!x.hiddenFromPlayer&&x.visibility!=="secret")).at(-1);
  $("#sidebar").innerHTML=`<div class="section"><h3>角色状态</h3>${stats}</div><div class="section"><h3>调查位置</h3><div class="kv"><span>剧本</span><b>${escapeHtml(state.scenario?.title||"未选择")}</b><span>地点</span><b>${escapeHtml(state.campaign.currentLocation||"-")}</b><span>节点</span><b>${escapeHtml(node?.title||"-")}</b><span>时间</span><b>${escapeHtml(state.campaign.currentTime||"-")}</b></div></div><div class="section"><h3>调查方向</h3>${chips(leads,"text")}</div><div class="section"><h3>未解决问题</h3>${chips(questions,"text")}</div><div class="section"><h3>剧情态势</h3>${situationMeter("张力",director.tension,director.maxTension,tensionStage(director.tension,director.maxTension))}${situationMeter("调查进度",director.progress,100,investigationStage(director.progress))}${director.activeThreats?.length?`<div class="muted small">当前威胁</div>${chips(director.activeThreats)}`:""}</div><div class="section"><h3>技能（★职业）</h3>${chips(skillEntries)}</div><div class="section"><h3>线索</h3>${renderClueSummary(state.clues)}</div><div class="section"><h3>物品 / 状态</h3>${chips([...(state.items||[]),...(state.statuses||[])])}</div><div class="section"><h3>NPC</h3>${chips(state.npcs)}</div>${lastCheck?`<div class="section"><h3>最近检定</h3><div class="kv"><span>项目</span><b>${escapeHtml(lastCheck.label)}</b><span>骰点</span><b>${escapeHtml(lastCheck.total??"跳过")}</b><span>结果</span><b>${escapeHtml(formatCheckResult(lastCheck))}</b></div></div>`:""}<div class="section"><h3>最近审计</h3>${recentLogs.length?recentLogs.map(x=>`<div class="audit">${escapeHtml(formatTime(x.time))} · ${escapeHtml(x.description)}</div>`).join(""):'<div class="muted">无</div>'}</div>`;
}
