    <div class="field"><label>规则严格度</label><select name="ruleStrictness"><option value="loose" ${state.config.ruleStrictness==="loose"?"selected":""}>宽松</option><option value="normal" ${state.config.ruleStrictness==="normal"?"selected":""}>正常</option><option value="strict" ${state.config.ruleStrictness==="strict"?"selected":""}>严格</option></select></div>
