function renderCharacter(){
  const system=state.config.system,c=state.character;let extra="";
  if(system==="coc7"){
    const attrs=c?.attributes||{str:50,con:50,siz:60,dex:50,app:50,int:60,pow:60,edu:70},derived=cocDerived(attrs),method=c?.creationMethod||"coc5",total=COC_ATTRIBUTE_KEYS.reduce((sum,key)=>sum+Number(attrs[key]||0),0),occupation=getOccupation(c?.occupationId||"private_investigator"),formulaId=c?.occupationFormulaId||occupation.formulas[0].id;
    extra=`<div class="grid three"><div class="field"><label>职业模板</label><select name="occupationId" id="cocOccupation">${COC_OCCUPATIONS.map(item=>`<option value="${item.id}" ${item.id===occupation.id?"selected":""}>${escapeHtml(item.name)}</option>`).join("")}</select></div><div class="field"><label>年龄</label><input name="age" type="number" min="15" max="99" value="${c?.age||28}"></div><div class="field"><label>创角方式</label><select name="creationMethod" id="cocCreationMethod"><option value="coc5" ${method==="coc5"?"selected":""}>天命五选一（.coc5）</option><option value="pointbuy480" ${method==="pointbuy480"?"selected":""}>480 购点（不含幸运）</option></select></div></div>
    <div class="card" style="margin:12px 0"><div class="row"><button id="rollCoc5Btn" class="btn" type="button">生成 5 组属性</button><button id="rollLuckBtn" class="btn" type="button">单独掷幸运</button><button id="fillPointBuyBtn" class="btn" type="button">填入 480 示例</button><span class="muted">480 购点只计算八项基础属性，幸运另算。</span></div><div id="cocRollResults" style="margin-top:10px"></div></div>
    <h3>八项基础属性</h3><div class="grid four">${COC_ATTRIBUTE_KEYS.map(key=>`<div class="field"><label>${COC_ATTRIBUTE_LABELS[key]}</label><input class="coc-attr" name="${key}" type="number" step="5" value="${attrs[key]}"></div>`).join("")}</div>
    <div class="grid three"><div class="field"><label>八项合计</label><input id="cocAttributeTotal" readonly value="${total}"></div><div class="field"><label>幸运 LUCK（不计入 480）</label><input id="cocLuck" name="luck" type="number" min="15" max="90" step="5" value="${c?.luck||50}"></div><div class="field"><label>最大 HP</label><input id="cocMaxHp" readonly value="${derived.maxHp}"></div><div class="field"><label>当前 HP</label><input id="cocCurrentHp" name="current_hp" type="number" min="0" value="${c?.hp??derived.maxHp}"></div><div class="field"><label>初始 SAN = POW</label><input id="cocInitialSan" readonly value="${derived.initialSan}"></div><div class="field"><label>当前 SAN</label><input id="cocCurrentSan" name="current_san" type="number" min="0" max="99" value="${c?.san??derived.initialSan}"></div></div>
    <div id="cocPointBuyNotice" class="notice ${method==="pointbuy480"&&total!==480?"warn":""}">当前八项合计：${total}${method==="pointbuy480"?` / 480，差值 ${480-total>=0?"+":""}${480-total}`:"；天命模式不限制合计"}。</div>
    <h3>职业与技能点</h3><div class="choice-panel"><div class="grid three"><div class="field"><label>职业点计算公式</label><select name="occupationFormulaId" id="cocOccupationFormula">${occupation.formulas.map(formula=>`<option value="${formula.id}" ${formula.id===formulaId?"selected":""}>${escapeHtml(formula.label)}</option>`).join("")}</select></div><div class="field"><label>信用评级范围</label><input id="cocCreditRange" readonly value="${occupation.credit[0]}～${occupation.credit[1]}"></div><div class="field"><label>职业说明</label><div class="notice">固定、可选和自由职业技能合计后再分配职业点。</div></div></div><div id="cocOccupationChoices"></div></div>
    <div class="skill-toolbar"><div class="field"><label>筛选技能</label><input id="skillFilter" placeholder="输入技能名"></div><div class="field"><label>分类</label><select id="skillCategory"><option value="all">全部分类</option>${Array.from(new Set(COC_SKILL_DEFINITIONS.map(x=>x.category))).map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join("")}</select></div><button id="autoAllocateSkillsBtn" class="btn" type="button">智能分配示例</button><button id="resetOccupationPointsBtn" class="btn" type="button">清空职业点</button><button id="resetInterestPointsBtn" class="btn" type="button">清空兴趣点</button></div>
    <div class="allocation-note">职业技能点按职业公式计算；个人兴趣点 = INT × 2。职业技能最终值上限 ${state.config.occupationSkillCap||80}，非职业技能上限 ${state.config.nonOccupationSkillCap||60}。克苏鲁神话锁定。</div>
    <div class="skill-table-wrap"><table class="skill-table"><thead><tr><th>技能</th><th>基础值</th><th>职业技能</th><th>职业点</th><th>兴趣点</th><th>最终值</th><th>困难 / 极难</th><th>上限</th></tr></thead><tbody id="cocSkillRows"></tbody></table></div><div id="cocPointStatus" class="point-status"></div>`;
  }else if(system==="dnd5e")extra=`<div class="grid three"><div class="field"><label>种族</label><input name="race" value="${escapeHtml(c?.race||"人类")}"></div><div class="field"><label>职业</label><input name="className" value="${escapeHtml(c?.className||"游荡者")}"></div><div class="field"><label>等级</label><input name="level" type="number" value="${c?.level||1}"></div><div class="field"><label>HP</label><input name="hp" type="number" value="${c?.maxHp||10}"></div><div class="field"><label>AC</label><input name="ac" type="number" value="${c?.ac||14}"></div><div class="field"><label>熟练加值</label><input name="proficiency" type="number" value="${c?.proficiency||2}"></div></div><h3>六项属性</h3><div class="grid three">${["str","dex","con","int","wis","cha"].map(k=>`<div class="field"><label>${k.toUpperCase()}</label><input name="${k}" type="number" value="${c?.attributes?.[k]||({str:10,dex:14,con:12,int:12,wis:14,cha:10}[k])}"></div>`).join("")}</div>`;
  else extra=`<div class="field"><label>HP</label><input name="hp" type="number" value="${c?.maxHp||10}"></div>`;
  $("#view-character").innerHTML=`<div class="hero"><h1>角色档案</h1><form id="characterForm" class="card"><div class="field"><label>姓名</label><input name="name" required value="${escapeHtml(c?.name||"")}"></div>${extra}<div class="field"><label>背景描述</label><textarea name="background">${escapeHtml(c?.background||c?.notes||"")}</textarea></div><div class="row"><button class="btn primary" type="submit">${c?"手动修正并记录":"创建角色"}</button><span class="muted">当前系统：${escapeHtml(system)}</span></div></form></div>`;
}
function scenarioCompatibility(scenario){const meta=scenario.metadata||{},occupationId=state.character?.occupationId,skills=Array.isArray(state.character?.skills)?state.character.skills:[];const occupationMatch=!meta.recommendedOccupations?.length||meta.recommendedOccupations.includes(occupationId),strongSkills=(meta.recommendedSkills||[]).filter(id=>(skills.find(skill=>skill.id===id)?.value||0)>=50);return{occupationMatch,strongSkills}}
