$("#improvSeedFileInput").addEventListener("change",async e=>{const file=e.target.files?.[0];e.target.value="";if(!file)return;if(file.size>2_000_000){toast("即兴种子超过 2MB 限制","danger");return}try{const text=await file.text();const parsed=safeJsonParse(text);if(!parsed.ok)throw new Error("JSON 解析失败");importImprovSeedObject(parsed.value)}catch(error){toast(`即兴种子导入失败：${error.message}`,"danger",6000)}});
